def bird_code(names):
    def code_for_name(name):
        parts = name.replace('-', ' ').split()
        if len(parts) == 1:
            return parts[0][:4].upper()
        elif len(parts) == 2:
            return (parts[0][:2] + parts[1][:2]).upper()
        elif len(parts) == 3:
            return (parts[0][0] + parts[1][0] + parts[2][:2]).upper()
        elif len(parts) == 4:
            return (parts[0][0] + parts[1][1] + parts[2][0] + parts[3][0]).upper()

    return [code_for_name(name) for name in names]
